  padding: 0 24px;
  flex-shrink: 0;
  color: var(--color-text);
  opacity: 0.85;
}

.marquee-separator {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--color-text);
  opacity: 0.3;
  margin: 0 8px;
