}

.logo a:hover {
  opacity: 0.6;
}

.desktop-nav {
  display: flex;
  gap: 36px;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  transition: opacity 0.3s ease;
}

.desktop-nav a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  background: none;
  border: none;
  position: relative;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
