.client-marquee {
  padding: 80px 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin-bottom: 16px;
}

.marquee-track {
  display: flex;
  align-items: center;
  animation: marquee-scroll 30s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation-direction: reverse;
  animation-duration: 35s;
}

.marquee-row:nth-child(3) .marquee-track {
  animation-duration: 28s;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  padding: 0 24px;
  flex-shrink: 0;
  color: var(--color-text);
  opacity: 0.85;
}

.marquee-separator {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--color-text);
  opacity: 0.3;
  margin: 0 8px;
}

@keyframes marquee-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* --- About Section --- */
.about-section {
  padding: 100px var(--side-padding) 120px;
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 80px;
  align-items: start;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  padding-top: 8px;
}

.about-content p {
  font-size: 1.125rem;
  line-height: 1.8;
  margin-bottom: 1.5em;
  max-width: 680px;
}

.about-content p:last-child {
  margin-bottom: 0;
}

/* --- Footer --- */
.site-footer {
  padding: 60px var(--side-padding);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-left {
  font-family: var(--font-serif);
  font-size: 1rem;
  font-weight: 700;
}

.footer-right {
  font-size: 0.8rem;
  color: var(--color-text-light);
}

/* ============================================
   Founder Letter Page (neweno.html)
   ============================================ */
.founder-letter {
  padding-top: 160px;
  padding-bottom: 120px;
  padding-left: var(--side-padding);
  padding-right: var(--side-padding);
  max-width: var(--content-width);
  margin: 0 auto;
}

.founder-letter .letter-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  margin-bottom: 40px;
}

.founder-letter h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 60px;
}

.founder-letter .letter-body p {
  font-size: 1.125rem;
  line-height: 1.9;
  margin-bottom: 1.75em;
  color: var(--color-text);
}

.founder-letter .letter-body p:last-child {
  margin-bottom: 0;
}

.founder-letter .letter-sign-off {
  margin-top: 60px;
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-style: italic;
  color: var(--color-text-light);
}

/* ============================================
   Services Page
   ============================================ */
.services-hero {
  padding-top: 160px;
  padding-bottom: 80px;
  padding-left: var(--side-padding);
  padding-right: var(--side-padding);
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-hero .philosophy-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  margin-bottom: 40px;
}

.services-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 40px;
}

.services-hero .philosophy-text {
  font-size: 1.125rem;
  line-height: 1.85;
  max-width: 680px;
  margin-bottom: 1.5em;
}

.services-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--side-padding);
}

.services-divider hr {
  border: none;
  border-top: 1px solid var(--color-border);
}

.services-detail {
  padding: 80px var(--side-padding) 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-detail h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 60px;
  font-style: italic;
}

.service-item {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 60px;
  margin-bottom: 60px;
  align-items: start;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-item h3 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  padding-top: 4px;
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.85;
  max-width: 620px;
}

/* ============================================
   Clients Page
   ============================================ */
.clients-hero {
  padding-top: 160px;
  padding-bottom: 40px;
  padding-left: var(--side-padding);
  padding-right: var(--side-padding);
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 6vw, 5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.clients-hero h1 span {
  font-weight: 400;
  font-style: italic;
  font-size: 0.5em;
  color: var(--color-text-light);
  margin-left: 16px;
}

.clients-grid {
  padding: 40px var(--side-padding) 120px;
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px 40px;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.client-card p {
  font-size: 0.925rem;
  line-height: 1.7;
  color: var(--color-text-light);
}

/* ============================================
   Contact Page
   ============================================ */
.contact-hero {
  padding-top: 200px;
  padding-bottom: 60px;
  padding-left: var(--side-padding);
  padding-right: var(--side-padding);
  text-align: center;
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.contact-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 15vw, 14rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 0.9;
  margin-bottom: 60px;
}

.contact-links {
  display: flex;
  gap: 40px;
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  color: var(--color-text-light);
  transition: color 0.3s ease;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}

.contact-links a:hover {
  color: var(--color-text);
  border-bottom-color: var(--color-text);
}

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 900px) {
  .desktop-nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .about-section {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .media-placeholder {
    min-height: 240px;
  }

  .media-placeholder:nth-child(2),
  .media-placeholder:nth-child(3) {
    margin-top: 0;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .contact-links {
    flex-direction: column;
    gap: 20px;
    align-items: center;
  }
}

@media (max-width: 600px) {
  .hero h1 {
    font-size: 2rem;
  }

  .site-header {
    padding: 20px var(--side-padding);
  }

  .hero {
    padding-top: 120px;
    padding-bottom: 48px;
  }

  .founder-letter {
    padding-top: 120px;
  }

  .services-hero {
    padding-top: 120px;
  }

  .clients-hero {
    padding-top: 120px;
  }

  .contact-hero {
    padding-top: 140px;
  }
}

@media (min-width: 901px) and (max-width: 1100px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

